import {useEffect,useState} from 'react';import {CreditCard,RefreshCw,ShieldCheck} from 'lucide-react';import {getPaymentProviderStatus} from '../../lib/practiceOperationsApi';
export function ExternalPayments(){const[data,setData]=useState(null),[state,setState]=useState('loading'),[error,setError]=useState('');const load=async()=>{setState('loading');setError('');try{setData(await getPaymentProviderStatus());setState('ready')}catch(reason){setError(reason.message||'Payment provider status could not be loaded.');setState('error')}};useEffect(()=>{void load()},[]);return <section className="space-y-5"><header><p className="text-xs font-bold uppercase tracking-widest text-blue-700">Payment foundation</p><h2 className="mt-1 text-3xl font-bold">Online payments</h2><p className="mt-2 text-sm text-slate-600">Provider-verified payment orders reconcile with governed invoices. Browser success is never financial authority.</p></header>{state==='loading'?<div aria-label="Loading payment provider" className="h-40 animate-pulse rounded-3xl bg-white"/>:state==='error'?<div className="rounded-3xl border border-red-200 bg-red-50 p-6"><p role="alert" className="text-sm text-red-800">{error}</p><button onClick={load} className="mt-4 min-h-11 rounded-xl border bg-white px-4"><RefreshCw className="mr-2 inline" size={16}/>Retry</button></div>:<article className={`rounded-3xl border p-6 ${data.status==='CONFIGURED'?'border-emerald-200 bg-emerald-50':'border-amber-200 bg-amber-50'}`}><div className="flex items-start gap-4"><span className="grid h-12 w-12 place-items-center rounded-2xl bg-white"><CreditCard/></span><div><h3 className="text-xl font-bold">{data.status==='CONFIGURED'?'Razorpay configured':'Live payment provider not configured'}</h3><p className="mt-2 text-sm leading-6">{data.status==='CONFIGURED'?'Orders require server verification and signed webhook reconciliation.':'No pay action is shown. Billing and manual payment recording remain available without false payment success.'}</p><p className="mt-3 text-xs font-semibold"><ShieldCheck className="mr-1 inline" size={15}/>Browser success authoritative: NO</p></div></div></article>}</section>}
